        for a in aInputs {
            mismatches.check(
                H.absoluteDifference(a, H.repeating(value)),
                HighwayReference.absoluteDifferenceF16(a, H.repeating(value)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

